{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];

  try {
    // STEALTH: Remove webdriver detection
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, 'webdriver', { get: () => false });
      Object.defineProperty(navigator, 'plugins', { get: () => [1, 2, 3, 4, 5] });
      Object.defineProperty(navigator, 'languages', { get: () => ['pt-BR', 'pt', 'en-US', 'en'] });
      window.chrome = { runtime: {} };
    });

    // STEALTH: User agent real
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
    await page.setViewport({ width: 1280, height: 800 });
    d.push('stealth');

    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'networkidle2', timeout: 30000 });
    d.push('page');
    await w(1500);

    // EMAIL - igual ao local
    const eInp = await page.$('#email_principal');
    if (eInp) {
      await eInp.click();
      await w(300);
      await eInp.type(EMAIL, { delay: 50 });
      d.push('email');
    }
    await w(800);

    // CONTINUAR - igual ao local
    await page.evaluate(() => {
      const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email'));
      if(b) b.click();
    });
    d.push('cont');

    // ESPERA MAIS TEMPO para o campo de senha aparecer
    await w(3000);

    // Tenta encontrar o campo de senha
    let pwdFound = false;
    for (let i = 0; i < 5; i++) {
      const pwd = await page.$('#pwdInput');
      if (pwd) {
        pwdFound = true;
        await pwd.click();
        await w(300);
        await pwd.type(SENHA, { delay: 50 });
        d.push('senha');
        break;
      }
      await w(1000);
    }

    if (!pwdFound) {
      // Debug: o que tem na pagina?
      const pageInfo = await page.evaluate(() => ({
        url: window.location.href,
        inputs: [...document.querySelectorAll('input')].map(i => i.id || i.name || i.type).join(','),
        text: document.body.innerText.substring(0, 200)
      }));
      d.push('NO PWD');
      d.push('url:' + pageInfo.url.substring(0, 50));
      d.push('inputs:' + pageInfo.inputs);
      return { success: false, error: 'pwdInput not found', debug: d, pageInfo };
    }

    await w(800);

    // ENTRAR
    await page.evaluate(() => {
      const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar');
      if(b) b.click();
    });
    d.push('entrar');

    await w(4000);

    // HAPVIDA
    await page.evaluate(() => {
      const img = document.querySelector('img[src*=\"hapvida\"]');
      if(img) {
        const p = img.closest('.clickable-element') || img.parentElement.parentElement;
        if(p) p.click();
      }
    });
    d.push('hap');
    await w(2000);

    const cookies = await page.cookies();
    const ls = await page.evaluate(() => {
      const items = {};
      for (let i = 0; i < window.localStorage.length; i++) {
        const key = window.localStorage.key(i);
        items[key] = window.localStorage.getItem(key);
      }
      return items;
    });
    d.push('done');

    return { success: true, fase: 'LOGIN', debug: d, cookies, localStorage: ls, url: page.url() };
  } catch (error) {
    d.push('ERR:' + error.message.substring(0, 50));
    return { success: false, error: error.message, debug: d };
  }
}"
}
